package i18n

// Textos de las pistas de puertos en Windows (ADR 0012 h): ahí no hay puertos privilegiados ni nftables ni setcap;
// lo que hace falta es una regla de entrada del Firewall de Windows que el usuario corre él mismo. El llamador
// (internal/diag/fileserve) elige estos códigos por sistema; los comandos de PowerShell y las IP son datos.
func init() {
	e := func(es, en string, args ...string) entry { return entry{Es: es, En: en, Args: args} }
	add(map[string]entry{
		"fileserve.hint.win_std_port":         e("IOS usa el puerto {std} de {proto}; escucho en el {port}. En Windows no hay puertos privilegiados, pero el Firewall de Windows debe dejar entrar el tráfico:", "IOS uses port {std} for {proto}; I listen on {port}. Windows has no privileged ports, but Windows Firewall must let the traffic in:", "std", "proto", "port"),
		"fileserve.hint.win_redirect":         e("regla de entrada del firewall (PowerShell como administrador, una vez; la app nunca la aplica; también sirve aceptar el diálogo del firewall, pero si lo CANCELAS Windows crea reglas de bloqueo que ganan a las de permiso: revísalas en Firewall de Windows → Configuración avanzada → Reglas de entrada): {cmd}", "inbound firewall rule (PowerShell as administrator, once; the app never applies it; accepting the firewall dialog also works, but if you CANCEL it Windows creates block rules that win over allow rules: check them in Windows Firewall → Advanced settings → Inbound Rules): {cmd}", "cmd"),
		"fileserve.hint.win_tftp_redir":       e("IOS siempre usa el puerto 69; en Windows se escucha ahí directo y solo hace falta esta regla de firewall (PowerShell como administrador):", "IOS always uses port 69; on Windows the server listens there directly and only this firewall rule is needed (PowerShell as administrator):"),
		"fileserve.hint.win_std_port_ok":      e("IOS usa el puerto {std} de {proto} y aquí se escucha en el {port}: Windows no tiene puertos privilegiados, solo falta que el Firewall de Windows deje entrar el tráfico:", "IOS uses port {std} for {proto} and this server listens on {port}: Windows has no privileged ports, only Windows Firewall must let the traffic in:", "std", "proto", "port"),
		"fileserve.hint.win_tftp_redir_other": e("IOS siempre usa el puerto 69 y en Windows no hay redirección: este servidor escucha en el {port}, así que ábrelo en el 69 para que IOS llegue. Esta regla de firewall (PowerShell como administrador) es para el {port}:", "IOS always uses port 69 and Windows has no redirection: this server listens on {port}, so open it on 69 for IOS to reach it. This firewall rule (PowerShell as administrator) is for {port}:", "port"),
		"fileserve.hint.win_no_exe":           e("(no se pudo saber o citar con seguridad la ruta de macuahuitld.exe; crea la regla de entrada a mano con -Program apuntando a ese archivo)", "(the path of macuahuitld.exe could not be determined or safely quoted; create the inbound rule by hand with -Program pointing to that file)"),
		// Variantes «código».windows: las elige i18n.Msg solo en Windows (mismos Args, sin Reason, Meta ni Extra).
		"mctl.transfer.hint.windows": func(es, en string) entry { return entry{Es: es, En: en, Args: tplArgs(es, en)} }("El equipo usa el puerto {std}; la app escucha en el {port}. En Windows no hay redirección: escucha en el {std} y abre el puerto con esta regla de firewall (la ejecutas tú, como administrador):\n  {nft}\nPara quitarla al terminar:\n  {remove}", "The device uses port {std}; the app listens on {port}. Windows has no redirection: listen on {std} and open the port with this firewall rule (you run it, as administrator):\n  {nft}\nTo remove it when done:\n  {remove}"), // Args deducidos como en catalog_mctl_a.go: subconjunto de los de la base (sin setcap, que en Windows no aplica)
	})
}
